BEGIN;
CREATE TABLE IF NOT EXISTS cemetery_tenant_memberships(tenant_id TEXT NOT NULL,user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('staff','manager','compliance','integration_operator','admin','viewer')),active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS governed_deathcare_cases(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_number TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('intake','identity_verified','authorized','scheduled','on_hold','services_complete','reconciled','closed')),version INTEGER NOT NULL DEFAULT 1,case_data JSONB NOT NULL CHECK(jsonb_typeof(case_data)='object'),idempotency_key TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,case_number),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS deathcare_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id BIGINT NOT NULL REFERENCES governed_deathcare_cases(id),actor_id BIGINT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS deathcare_outbox(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,case_id BIGINT NOT NULL REFERENCES governed_deathcare_cases(id),provider TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','processing','succeeded','failed','dead_letter')),attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,payload JSONB NOT NULL DEFAULT '{}',requested_by BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS deathcare_cases_tenant_state_idx ON governed_deathcare_cases(tenant_id,state);CREATE INDEX IF NOT EXISTS deathcare_outbox_status_idx ON deathcare_outbox(status,created_at);
COMMIT;
